const updateNormalisieren = node({ type: "n8n-nodes-base.code", version: 2, config: { name: "Update normalisieren", parameters: { jsCode: "const b = $json || {};\nconst cb = b.callback_query || null;\nconst msg = cb ? (cb.message || {}) : (b.message || b.edited_message || {});\nconst chat = msg.chat || {};\nconst from = cb ? (cb.from || {}) : (msg.from || {});\nconst chat_id = String(chat.id || from.id || '');\nlet typ = 'unbekannt';\nlet text = '';\nlet callback_data = '';\nlet callback_query_id = '';\nlet photo_b64 = '';\nif (cb) {\n  typ = 'callback';\n  callback_data = String(cb.data || '');\n  callback_query_id = String(cb.id || '');\n} else if (msg.photo) {\n  typ = 'foto';\n  text = String(msg.caption || '').trim();\n  try { const buf = await this.helpers.getBinaryDataBuffer(0, 'data'); photo_b64 = buf.toString('base64'); } catch (e) { photo_b64 = ''; }\n} else if (msg.text) {\n  typ = 'text';\n  text = String(msg.text).trim();\n}\nreturn [{ json: { quelle: 'telegram', chat_id: chat_id, typ: typ, text: text, callback_data: callback_data, callback_query_id: callback_query_id, message_id: String(msg.message_id || ''), has_photo: photo_b64 !== '', photo_b64: photo_b64 } }];" }, position: [224, 1184] }, output: [{}] });

